sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float range;
uniform float redHue;
uniform float redSaturation;
uniform float redLightness;
uniform float orangeHue;
uniform float orangeSaturation;
uniform float orangeLightness;
uniform float yellowHue;
uniform float yellowSaturation;
uniform float yellowLightness;
uniform float greenHue;
uniform float greenSaturation;
uniform float greenLightness;
uniform float cyanHue;
uniform float cyanSaturation;
uniform float cyanLightness;
uniform float blueHue;
uniform float blueSaturation;
uniform float blueLightness;
uniform float purpleHue;
uniform float purpleSaturation;
uniform float purpleLightness;
uniform float magentaHue;
uniform float magentaSaturation;
uniform float magentaLightness;
uniform float brightness;
uniform float opacity;
uniform float blend;
float tent(float h, float a, float b, float c) { return h < b ? smoothstep(a, b, h) : 1.0 - smoothstep(b, c, h); }
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float3 base = float3(src.rgb) / float(src.a);
    float top = max(base.r, max(base.g, base.b));
    float d = top - min(base.r, min(base.g, base.b));
    float h = 0.0;
    if (d > 0.00001) {
        if (top == base.r) h = (base.g - base.b) / d;
        else if (top == base.g) h = (base.b - base.r) / d + 2.0;
        else h = (base.r - base.g) / d + 4.0;
        h = fract(h / 6.0) * 360.0;
    }
    float3 shift = (tent(h, -60.0, 0.0, 30.0) + tent(h, 300.0, 360.0, 420.0)) * float3(redHue, redSaturation, redLightness)
        + tent(h, 0.0, 30.0, 60.0) * float3(orangeHue, orangeSaturation, orangeLightness)
        + tent(h, 30.0, 60.0, 120.0) * float3(yellowHue, yellowSaturation, yellowLightness)
        + tent(h, 60.0, 120.0, 180.0) * float3(greenHue, greenSaturation, greenLightness)
        + tent(h, 120.0, 180.0, 240.0) * float3(cyanHue, cyanSaturation, cyanLightness)
        + tent(h, 180.0, 240.0, 270.0) * float3(blueHue, blueSaturation, blueLightness)
        + tent(h, 240.0, 270.0, 300.0) * float3(purpleHue, purpleSaturation, purpleLightness)
        + tent(h, 270.0, 300.0, 360.0) * float3(magentaHue, magentaSaturation, magentaLightness);
    shift *= smoothstep(0.0, 0.2, d) / 100.0;
    float turn = radians(shift.x * 30.0);
    float3 k = float3(0.57735);
    float3 rgb = base * cos(turn) + cross(k, base) * sin(turn) + k * dot(k, base) * (1.0 - cos(turn));
    float y = dot(rgb, float3(0.2126, 0.7152, 0.0722));
    rgb = float3(y) + (rgb - float3(y)) * (1.0 + shift.y);
    rgb = shift.z < 0.0 ? rgb * (1.0 + 0.6 * shift.z) : rgb + (1.0 - rgb) * 0.6 * shift.z;
    rgb = clamp(rgb * max(brightness, 0.0), 0.0, 1.0);
    float3 mixed = blend < 0.5 ? rgb : blend < 1.5 ? base * rgb : base + rgb - base * rgb;
    rgb = mix(base, mixed, clamp(opacity, 0.0, 1.0));
    return half4(half3(rgb) * src.a, src.a);
}
